import {hydrateAppearanceState,clearMorphologyCache} from './lab-morphology.js';
// Isolated local HOST simulation. No wallet, real-token or native transaction calls.
const PREFIX='/api/lab-sim';
const PROFILE='BIO-LOCAL-PLAYTEST1';
const KEY='mogusbio:lab-sim:pending:v1';
const hex=v=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v);
const plain=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
const copy=v=>structuredClone(v);
const ENGLISH={LAB_LAUNCH_TEXT:'Use a listing name of 1–48 UTF-8 bytes and a description up to 160 bytes.',LAB_LAUNCH_OWNER:'Choose a live specimen owned by this account. Staked or listed specimens cannot be launched.',PLAYTEST_REVISION:'Another operation updated this account. The latest ledger is loaded; check it before continuing.',PLAYTEST_RUN:'This simulation has been restarted. Continue with the new run.',PLAYTEST_RETRY_CONFLICT:'This operation ID belongs to another request. Refresh before continuing.',PLAYTEST_SESSION:'Start your local test account to continue.',PLAYTEST_ACCOUNT_LIMIT:'This local simulator has reached its account limit. Continue an existing session.',PLAYTEST_FIELDS:'Some settings are outside the accepted model. Check the selected inputs.',PLAYTEST_ORIGIN:'This simulator accepts requests from the local laboratory only.',PLAYTEST_NOTHING_TO_CLAIM:'No settled LAB is available to claim yet.',PLAYTEST_WORK_UNAVAILABLE:'This specimen is not available for that operation. Check ownership and staking status.',MARKET_SELF_TRADE:'You cannot buy your own listing.',MARKET_NOT_OPEN:'This listing has already been sold or cancelled.',MARKET_FUNDS:'The buyer does not have enough simulation SOL.',MARKET_MATERIAL_BALANCE:'Some materials are already used or held in a listing.',MARKET_WORK_OWNER:'Only your live, unconsumed specimens can be listed.',PROCESSOR:'The nutrient-processing path cannot support the requested load.',CONTROL:'The design cannot complete its control response.',MECHANICAL:'The actuator cannot complete the mechanical task.',CUT:'A transport layer exceeds its capacity.',PORT_CAP:'A connection exceeds its port capacity.',QUALITY:'The design does not meet the requested quality.',INTEGER:'Flow fractions do not resolve into exact model units.',PLAYTEST_LAB:'Not enough settled LAB. Stake a specimen, settle simulation hours and claim its output.'};
export function labErrorMessage(error){const code=error?.code;return ENGLISH[code]??(typeof code==='string'&&/^[A-Z][A-Z0-9_]{1,60}$/.test(code)?`This operation could not complete (${code}). Your ledger is unchanged.`:'The local service is unavailable. Your draft and pending operation are preserved.');}
export function formatLabUnits(value,decimals=6){
  if(typeof value!=='string'||!/^(?:0|[1-9]\d*)$/.test(value)||!Number.isInteger(decimals)||decimals<0||decimals>9)return '—';
  const n=BigInt(value),base=10n**BigInt(decimals),tail=(n%base).toString().padStart(decimals,'0').replace(/0+$/,'');return `${n/base}${tail?'.'+tail:''}`;
}
export function decimalLabUnits(value,decimals=9){
  if(typeof value!=='string'||value.length>30||!new RegExp(`^(?:0|[1-9]\\d*)(?:\\.\\d{1,${decimals}})?$`).test(value))throw Object.assign(Error('AMOUNT'),{code:'PLAYTEST_FIELDS'});
  const [a,b='']=value.split('.'),n=BigInt(a)*10n**BigInt(decimals)+BigInt(b.padEnd(decimals,'0'));if(n>18446744073709551615n)throw Object.assign(Error('AMOUNT'),{code:'PLAYTEST_FIELDS'});return n.toString();
}
export async function readSimJSON(fetchImpl,url,init={},timeoutMs=30000){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeoutMs);let reader,abortHandler;const aborted=new Promise((_,reject)=>{abortHandler=()=>reject(Object.assign(Error('TIMEOUT'),{uncertain:true}));controller.signal.addEventListener('abort',abortHandler,{once:true});});const bounded=p=>Promise.race([Promise.resolve(p),aborted]);
  try{const response=await bounded(fetchImpl(url,{...init,credentials:'same-origin',cache:'no-store',redirect:'error',headers:{accept:'application/json',...init.headers},signal:controller.signal}));if(!/\bapplication\/json\b/i.test(response.headers?.get('content-type')??'')||!response.body?.getReader)throw Error('SIM_RESPONSE');reader=response.body.getReader();const chunks=[];let size=0;for(;;){const part=await bounded(reader.read());if(part.done)break;size+=part.value.byteLength;if(size>1048576)throw Error('SIM_RESPONSE_SIZE');chunks.push(part.value);}const bytes=new Uint8Array(size);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}const data=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));if(!plain(data))throw Error('SIM_RESPONSE');if(!response.ok){const authoritative=data.profile===PROFILE&&data.networkSubmitted===false&&typeof data.code==='string'&&/^[A-Z][A-Z0-9_]{1,60}$/.test(data.code);throw Object.assign(Error('SIM_OPERATION'),{code:authoritative?data.code:undefined,serverReply:authoritative,uncertain:response.status>=500||data.outcome==='UNKNOWN'||!authoritative&&init.method==='POST'});}return data;
  }catch(error){if(error?.serverReply===true||error?.uncertain===true)throw error;throw Object.assign(Error('SIM_UNAVAILABLE'),{uncertain:init.method==='POST'});}finally{clearTimeout(timer);controller.signal.removeEventListener('abort',abortHandler);if(reader){void reader.cancel().catch(()=>{});reader.releaseLock();}}
}
export function createLabSimClient({fetchImpl=globalThis.fetch,storage,randomBytes=()=>globalThis.crypto.getRandomValues(new Uint8Array(32)),onChange=()=>{},onStatus=()=>{}}={}){
  let current=null,pending=null,busy=false,enabled=false,closed=false;
  const random=()=>[...randomBytes()].map(n=>n.toString(16).padStart(2,'0')).join('');
  try{const value=JSON.parse(storage?.getItem(KEY)??'null');if(plain(value)&&['start','action','reset'].includes(value.kind)&&plain(value.body)&&hex(value.body.requestId)&&Object.keys(value).every(k=>['kind','body'].includes(k)))pending=value;}catch{}
  const persist=()=>{try{if(pending)storage?.setItem(KEY,JSON.stringify(pending));else storage?.removeItem(KEY);}catch{}};
  const notify=()=>{if(!closed)onChange({current:current?copy(current):null,pending:pending?copy(pending):null,busy,enabled});};
  const accept=data=>{if(data.profile!==PROFILE||data.networkSubmitted!==false)throw Error('SIM_IDENTITY');if(data.authenticated===false){current=null;clearMorphologyCache();return;}if(!hex(data.runId)||!/^\d{1,9}$/.test(data.revision)||data.state?.profile!=='BIO-PLAYTEST-SNAPSHOT1'||data.state.scope?.networkSubmitted!==false)throw Error('SIM_IDENTITY');if(current?.runId===data.runId&&BigInt(data.revision)<BigInt(current.revision))return;if(current?.runId!==data.runId)clearMorphologyCache();hydrateAppearanceState(data.state);current=data;};
  async function refresh(){if(closed||busy)return;busy=true;notify();try{const cfg=await readSimJSON(fetchImpl,`${PREFIX}/config`);if(closed)return;if(cfg.enabled!==true||cfg.referenceModel!==true||cfg.networkSubmitted!==false)throw Error('SIM_DISABLED');enabled=true;const data=await readSimJSON(fetchImpl,`${PREFIX}/state`);if(closed)return;accept(data);onStatus(current?'Your local ledger is up to date.':'Start a test account. No wallet or real funds are needed.');}catch(error){if(closed)return;enabled=false;onStatus(labErrorMessage(error),true);}finally{busy=false;notify();}}
  async function retry(){if(closed||busy||!pending)return;busy=true;notify();const own=copy(pending);onStatus(own.kind==='start'?'Preparing your isolated simulation ledger…':'Applying this operation to your local ledger…');try{const data=await readSimJSON(fetchImpl,`${PREFIX}/${own.kind}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(own.body)},60000);if(closed)return;try{if(data.authenticated===false)throw Error('SIM_IDENTITY');accept(data);}catch{throw Object.assign(Error('SIM_UNCONFIRMED_RESPONSE'),{uncertain:true});}pending=null;persist();onStatus(own.kind==='start'?'Your isolated simulation account is ready.':own.kind==='reset'?'A fresh local simulation is ready.':'Operation completed. Balances and ownership are updated.');return copy(data);}
    catch(error){if(closed)return;if(!error.uncertain){pending=null;persist();try{const recovered=await readSimJSON(fetchImpl,`${PREFIX}/state`);if(closed)return;accept(recovered);}catch{} }if(closed)return;onStatus(error.uncertain?'The result is not confirmed yet. Use Retry pending operation to check the exact same request.':labErrorMessage(error),true);}finally{busy=false;notify();}}
  async function start(){if(closed||busy||pending||current)return;if(!enabled){await refresh();if(closed||!enabled||current||busy||pending)return;}pending={kind:'start',body:{requestId:random()}};persist();return await retry();}
  async function act(action,params={}){if(closed||busy||pending||!current)return;pending={kind:'action',body:{runId:current.runId,revision:current.revision,requestId:random(),action,params:copy(params)}};persist();return await retry();}
  async function reset(){if(closed||busy||pending||!current)return;pending={kind:'reset',body:{runId:current.runId,revision:current.revision,requestId:random()}};persist();return await retry();}
  return{refresh,start,act,retry,reset,get snapshot(){return{current:current?copy(current):null,pending:pending?copy(pending):null,busy,enabled};},close(){closed=true;clearMorphologyCache();}};
}
